"""Master-side code generated from the same .rudra file: C++ header, Python client, protocol doc, info."""
from __future__ import annotations

from .check import Checked
from .syntax import IO, Var, fmt_expr
from .util import VERSION, fnv31


def _hb_ms(ck: Checked):
    for e in ck.node.events:
        if e.kind == "heartbeat" and not e.off:
            return e.ms
    return None


def protocol_hash(ck: Checked) -> int:
    """31-bit fingerprint of everything the master depends on: name, baud, heartbeat, commands, messages."""
    n = ck.node
    sig = "|".join([
        n.name, str(n.baud), str(_hb_ms(ck) or 0),
        ",".join(sorted(f"{c}/{len(p)}" for c, p in ck.commands)),
        ",".join(sorted(f"{m}/{int(v)}" for m, v in ck.messages.items())),
        # v0.4 parts are only added when used, so v0.3 programs keep their fingerprint
        *([f"states:{','.join(ck.states)}"] if ck.states else []),
        *([f"addr:{n.address}"] if n.address is not None else []),
        *(["blackbox"] if n.blackbox_pos is not None else []),
    ])
    return fnv31(sig)


def _cls(name: str) -> str:
    return "".join(p.capitalize() for p in name.split("_")) + "Link"


def libraries(ck: Checked):
    libs = []
    kinds = {d.kind for d in ck.node.decls if isinstance(d, IO)}
    if "neopixel" in kinds:
        libs.append("Adafruit NeoPixel")
    if "servo" in kinds:
        libs.append("ESP32Servo" if ck.node.target.startswith("esp") else "Servo (built in)")
    return libs


BB_CODES = {1: "boot", 2: "link lost", 3: "state", 4: "blocked", 5: "motor timeout", 6: "bad index"}


# --------------------------------------------------------------------------
def gen_python(ck: Checked) -> str:
    n = ck.node
    hb = _hb_ms(ck)
    L = [f'"""Master-side link for node "{n.name}". Generated by rudrac {VERSION} -- do not edit by hand.',
         "",
         "Works with any object that has write(bytes) and readline() -> bytes, e.g. a pyserial Serial",
         'opened with  serial.Serial(port, BAUD, timeout=0.2) .',
         '"""',
         "",
         f'NODE = "{n.name}"',
         f"BAUD = {n.baud}",
         f"PROTO_HASH = {protocol_hash(ck)}   # fingerprint of this node's protocol; verify() compares it with the node's",
         f"HEARTBEAT_MS = {hb if hb else 'None'}   # node goes to its safe state after this much silence",
         f"KEEPALIVE_MS = {max(hb // 3, 1) if hb else 'None'}   # send ping() at least this often",
         *([f"BLACKBOX_CODES = {BB_CODES!r}"] if n.blackbox_pos is not None else []),
         *([f"ADDRESS = {n.address}   # this node's address on the shared bus (@0 is the broadcast address)"] if ck.bus else []),
         *([f"STATES = {{{', '.join(f'{s_!r}: {k}' for k, s_ in enumerate(ck.states))}}}   # state name -> number reported by STATE"]
           if ck.states else []),
         f"COMMANDS = {{{', '.join(f'{c!r}: {len(p)}' for c, p in ck.commands)}}}   # name -> number of arguments",
         f"MESSAGES = {{{', '.join(f'{m!r}: {v}' for m, v in ck.messages.items())}}}   # name -> carries a value",
         "",
         "",
         f"class {_cls(n.name)}:",
         "    def __init__(self, port):",
         "        self.port = port",
         "",
         "    def _send(self, line):",
         *(['        self.port.write((f"@{ADDRESS} " + line + "\\n").encode("ascii"))'] if ck.bus else
           ['        self.port.write((line + "\\n").encode("ascii"))']),
         "",
         "    def ping(self):",
         '        """Resets the node\'s heartbeat timer. The node answers PONG."""',
         '        self._send("PING")',
         "",
         "    def who(self):",
         '        """Asks the node for its protocol fingerprint (answer: WHO <hash>)."""',
         '        self._send("WHO")',
         "",
         "    def status(self):",
         '        """Asks how many writes the node refused because of a never rule (answer: STATUS <count>)."""',
         '        self._send("STATUS")',
         "",
         "    def verify(self, max_lines=8):",
         '        """True if the node answers WHO with the fingerprint this client was generated for."""',
         "        self.who()",
         "        for _ in range(max_lines):",
         "            msg = self.read_message()",
         "            if msg is None:",
         "                continue",
         '            if msg[0] == "WHO":',
         "                return msg[1] == PROTO_HASH",
         "        return False"]
    if ck.states:
        L += ["", "    def state(self):",
              '        """Asks which state the node is in (answer: STATE <number>, see STATES)."""',
              '        self._send("STATE")']
    if n.blackbox_pos is not None:
        L += ["", "    def log(self, max_lines=80):",
              '        """Reads the node\'s black box. Returns a list of (time_ms, what, argument), oldest first."""',
              '        self._send("LOG")',
              "        out = []",
              "        for _ in range(max_lines):",
              "            f = self.read_fields()",
              "            if f is None:",
              "                continue",
              '            if f[0] == "LOGEND":',
              "                return out",
              '            if f[0] == "LOG" and len(f[1]) == 3:',
              "                out.append((f[1][0], BLACKBOX_CODES.get(f[1][1], str(f[1][1])), f[1][2]))",
              "        return out"]
    for name, params in ck.commands:
        sig = ", ".join(["self"] + params)
        body = " ".join([name] + [f"{{int({p})}}" for p in params])
        L += ["", f"    def cmd_{name}({sig}):", f'        self._send(f"{body}")']
    L += ["",
          "    def read_fields(self):",
          '        """Returns (name, [ints]) for one line from this node, or None on timeout / a line that is not ours."""',
          "        raw = self.port.readline()",
          "        if not raw:",
          "            return None",
          '        parts = raw.decode("ascii", "replace").strip().split()']
    if ck.bus:
        L += ['        if parts and parts[0].startswith("@"):',
              "            try:",
              "                who = int(parts[0][1:])",
              "            except ValueError:",
              "                return None",
              "            if who != ADDRESS:",
              "                return None   # another node's reply",
              "            parts = parts[1:]"]
    L += ["        if not parts:",
          "            return None",
          "        vals = []",
          "        for tok in parts[1:]:",
          "            try:",
          "                vals.append(int(tok))",
          "            except ValueError:",
          "                break",
          "        return parts[0], vals",
          "",
          "    def read_message(self):",
          '        """Returns (name, value) for one line from the node, or None on timeout.',
          '        value is an int, or None for messages without a value. Built-ins: PONG, ERR."""',
          "        f = self.read_fields()",
          "        if f is None:",
          "            return None",
          "        return f[0], (f[1][0] if f[1] else None)",
          ""]
    return "\n".join(L)


# --------------------------------------------------------------------------
def gen_cpp(ck: Checked) -> str:
    n = ck.node
    p = n.name
    hb = _hb_ms(ck)
    L = [f"// Master-side link for node \"{p}\". Generated by rudrac {VERSION} -- do not edit by hand.",
         "// Include this in the main board's sketch. 'port' is any Print, e.g. Serial1.",
         f"#ifndef RUDRA_LINK_{p.upper()}_H",
         f"#define RUDRA_LINK_{p.upper()}_H",
         "#include <Arduino.h>",
         "#include <string.h>",
         "#include <stdlib.h>",
         "",
         f"#define {p.upper()}_BAUD {n.baud}"]
    if hb:
        L += [f"#define {p.upper()}_HEARTBEAT_MS {hb}   /* node goes safe after this much silence */",
              f"#define {p.upper()}_KEEPALIVE_MS {max(hb // 3, 1)}   /* call {p}_ping at least this often */"]
    pre = f'port.print("@{n.address} "); ' if ck.bus else ""
    if ck.bus:
        L.append(f"#define {p.upper()}_ADDRESS {n.address}   /* shared-bus address; @0 reaches every node */")
    L += [f"#define {p.upper()}_PROTO_HASH {protocol_hash(ck)}L   /* compare with the number in the node's WHO reply */",
          "", f"static inline void {p}_ping(Print &port) {{ {pre}port.println(\"PING\"); }}",
          f"static inline void {p}_who(Print &port) {{ {pre}port.println(\"WHO\"); }}",
          f"static inline void {p}_status(Print &port) {{ {pre}port.println(\"STATUS\"); }}"]
    if ck.states:
        for k, s_ in enumerate(ck.states):
            L.append(f"#define {p.upper()}_STATE_{s_.upper()} {k}")
        L.append(f"static inline void {p}_state(Print &port) {{ {pre}port.println(\"STATE\"); }}")
    if n.blackbox_pos is not None:
        L.append(f"static inline void {p}_log(Print &port) {{ {pre}port.println(\"LOG\"); }}   /* answer: LOG t code arg ... LOGEND n */")
    for name, params in ck.commands:
        sig = ", ".join(["Print &port"] + [f"long {a}" for a in params])
        L.append(f"static inline void {p}_{name}({sig}) {{")
        if ck.bus:
            L.append(f'  port.print("@{n.address} ");')
        L.append(f'  port.print("{name}");')
        for a in params:
            L.append(f'  port.print(" "); port.print({a});')
        L.append('  port.println("");')
        L.append("}")
    L += ["",
          f"/* One parsed line from the node. 'name' points into the buffer you passed to {p}_parse. */",
          f"struct {p}_msg {{ const char *name; bool has_value; long value; long addr; }};   /* addr: bus address of the sender, -1 if none */",
          "",
          f"/* Splits a received line in place (modifies it). Returns false for an empty line. */",
          f"static inline bool {p}_parse(char *line, {p}_msg *m) {{",
          "  while (*line == ' ') line++;",
          "  if (!*line) return false;",
          "  m->addr = -1;",
          "  if (*line == '@') {",
          "    char *e = NULL;",
          "    m->addr = strtol(line + 1, &e, 10);",
          "    line = e;",
          "    while (*line == ' ') line++;",
          "    if (!*line) return false;",
          "  }",
          "  m->name = line;",
          "  while (*line && *line != ' ') line++;",
          "  m->has_value = false; m->value = 0;",
          "  if (*line) {",
          "    *line++ = 0;",
          "    while (*line == ' ') line++;",
          "    if (*line) { m->has_value = true; m->value = strtol(line, NULL, 10); }",
          "  }",
          "  return true;",
          "}",
          "",
          "/* Message names: */"]
    for m in list(ck.messages) + ["PONG", "ERR", "WHO", "STATUS"] + (["STATE"] if ck.states else []) + \
            (["LOG", "LOGEND"] if n.blackbox_pos is not None else []):
        L.append(f'#define {p.upper()}_MSG_{m} "{m}"')
    L += ["", "#endif", ""]
    return "\n".join(L)


# --------------------------------------------------------------------------
def gen_protocol(ck: Checked) -> str:
    n = ck.node
    hb = _hb_ms(ck)
    L = [f"# Protocol of node `{n.name}`", "",
         f"Generated by rudrac {VERSION} from the `.rudra` source. Do not edit by hand.", "",
         f"* Board: `{n.target}`",
         f"* Link: serial, **{n.baud} baud**, 8N1, plain text, one message per line ending in `\\n` (`\\r` is ignored)",
         "* Lines longer than 31 characters are dropped",
         "* Numbers are base-10 integers, separated by single spaces",
         f"* Protocol fingerprint: `{protocol_hash(ck)}` (the node reports it in answer to `WHO`)", ""]
    if ck.bus:
        L += ["## Shared bus", "",
              f"This node has **address {n.address}**. Every line to it starts with `@{n.address} `, e.g. `@{n.address} PING`. "
              "Lines for other addresses are ignored. `@0` is the **broadcast** address: every node executes the line "
              "(and it counts as a heartbeat) but **nobody answers**, so replies never collide on the wire. "
              f"Every reply from this node starts with `@{n.address} `. "
              "A node speaks only when it is asked (`send` is only allowed inside `on` handlers on a bus).",
              *([f"The driver-enable pin of the RS485 transceiver is raised just for the duration of each reply."]
                if n.rs485_pin is not None else []), ""]
    if hb:
        L += [f"## Heartbeat", "",
              f"The node puts **every output in its declared safe state** if it hears nothing for **{hb} ms**, "
              "and holds that state until it hears a valid command again. "
              f"Send `PING` (or any valid command) at least every **{max(hb // 3, 1)} ms**.", ""]
    else:
        L += ["## Heartbeat", "",
              "**None.** This node keeps its outputs as they are if the master goes quiet.", ""]
    L += ["## Commands (master to node)", "", "| Line | Arguments | Notes |", "|---|---|---|",
          "| `PING` | none | resets the heartbeat; node replies `PONG` |",
          f"| `WHO` | none | node replies `WHO {protocol_hash(ck)}`: a fingerprint of this protocol, to detect a master/node version mismatch |",
          "| `STATUS` | none | node replies `STATUS <n>`: writes refused so far because of a `never` rule |"]
    if ck.states:
        L.append(f"| `STATE` | none | node replies `STATE <n>`: " + ", ".join(f"{k} = {s_}" for k, s_ in enumerate(ck.states)) + " |")
    if n.blackbox_pos is not None:
        L.append(f"| `LOG` | none | node replies with its black box: `LOG <ms> <code> <arg>` per entry (oldest first), then `LOGEND <total>`. "
                 f"Codes: " + ", ".join(f"{k} = {v}" for k, v in BB_CODES.items()) + f". Keeps the last {n.blackbox} events, RAM only |")
    for name, params in ck.commands:
        ex = " ".join([name] + [str(k + 1) for k in range(len(params))])
        where = ""
        if ck.states:
            sts = sorted({e.state for e in n.events if e.kind == "on" and e.name == name and e.state})
            glob = any(e.kind == "on" and e.name == name and e.state is None for e in n.events)
            if sts and not glob:
                where = " Only in state: " + ", ".join(sts) + " (otherwise `ERR`)."
        L.append(f"| `{ex}` | {', '.join(params) or 'none'} | node replies `ERR` if arguments are missing.{where} |")
    L += ["", "Unknown commands are answered with `ERR`. Extra arguments are ignored.", "",
          "## Messages (node to master)", "", "| Line | Meaning |", "|---|---|",
          "| `PONG` | answer to `PING` |", "| `ERR` | unknown command or missing argument |"]
    for m, has in ck.messages.items():
        L.append(f"| `{m}{' <int>' if has else ''}` | sent by the node's script |")
    L.append("")
    return "\n".join(L)


# --------------------------------------------------------------------------
def info(ck: Checked) -> str:
    n = ck.node
    hb = _hb_ms(ck)
    ios = [d for d in n.decls if isinstance(d, IO)]
    vars_ = [d for d in n.decls if isinstance(d, Var)]
    L = [f"node {n.name}   target {n.target}   serial {n.baud}", "", "Wiring:"]
    for d in ios:
        if d.kind == "i2c":
            where = f"I2C addr 0x{d.cfg['addr']:02X}" + (f" reg {d.cfg['reg']}" if d.cfg["reg"] is not None else "")
        elif d.kind in ("motor", "stepper", "ultrasonic"):
            where = ", ".join(f"{r} {t}" for r, (t, _p) in d.pins.items())
        else:
            where = f"pin {d.pin_text}"
        extra = []
        if d.kind == "neopixel":
            extra.append(f"{d.cfg['count']} pixels")
        if d.cfg.get("debounce"):
            extra.append(f"debounce {d.cfg['debounce']}ms")
        if d.kind == "motor":
            extra.append(f"limit {d.cfg['limit']}%")
            if d.cfg.get("ramp"):
                extra.append(f"ramp {d.cfg['ramp']}%/s")
            if d.cfg.get("timeout"):
                extra.append(f"timeout {d.cfg['timeout']}ms")
        if d.kind == "stepper":
            extra.append(f"{d.cfg['rate']} steps/s")
        if d.pullup:
            extra.append("pullup")
        if d.invert:
            extra.append("active-low")
        if d.direction == "output":
            sv = d.cfg["safe"]
            if d.kind == "neopixel":
                extra.append("safe " + ("off" if sv == (0, 0, 0) else f"{sv[0]},{sv[1]},{sv[2]}"))
            elif d.kind == "stepper":
                extra.append(f"safe position {sv}")
            else:
                extra.append("safe " + (("on" if sv else "off") if d.kind == "digital" else str(sv)))
        L.append(f"  {d.direction:6} {d.name:12} {d.kind:9} {where:20} {', '.join(extra)}")
    if ck.bus:
        L += ["", f"Shared bus: address {n.address}" + (f", RS485 direction pin {n.rs485_text}" if n.rs485_pin is not None else "")
              + "   (answers only when asked; @0 broadcast is never answered)"]
    if ck.states:
        L += ["", "States: " + ", ".join(f"{s_} ({k})" for k, s_ in enumerate(ck.states)) + "   (starts in " + ck.states[0] + ")"]
    if ck.rules:
        L += ["", "Interlocks (the safe state is proved to satisfy them; every write is checked against them):"]
        L += [f"  never {fmt_expr(r.expr)}" for r in ck.rules]
    L += ["", "Commands:"]
    L.append("  PING" + ("   (heartbeat keep-alive)" if hb else ""))
    if ck.states:
        L.append("  STATE    (which state the node is in)")
    if n.blackbox_pos is not None:
        L.append(f"  LOG      (black box: last {n.blackbox} events)")
    L.append("  WHO      (protocol fingerprint)")
    L.append("  STATUS   (writes refused by a never rule)")
    for name, params in ck.commands:
        L.append("  " + " ".join([name] + [f"<{a}>" for a in params]))
    L += ["", "Messages:"]
    L += [f"  {m}{' <int>' if has else ''}" for m, has in ck.messages.items()] or ["  (none besides PONG / ERR)"]
    L += ["", f"Heartbeat: " + (f"{hb} ms, then all outputs go to their safe states" if hb else "OFF"),
          f"Protocol fingerprint: {protocol_hash(ck)}"]
    # rough static-RAM estimate: only what generated code itself adds
    ram = 32 + 8
    ram += sum(4 * len(d.slots) * (d.size or 1) for d in vars_)
    ram += sum(4 for d in ios if d.direction == "output" and d.kind not in ("neopixel",))
    ram += sum(4 for e in n.events if e.kind == "every")
    ram += sum(3 * d.cfg["count"] + 16 for d in ios if d.kind == "neopixel")
    ram += sum(12 for d in ios if d.kind == "servo")
    ram += sum(8 for d in ios if d.kind in ("motor", "stepper")) + (1 if ck.states else 0)
    ram += sum(6 for d in ios if d.direction == "input" and d.cfg.get("debounce"))
    ram += (9 * n.blackbox + 12) if n.blackbox_pos is not None else 0
    L += ["", f"Static RAM added by the generated code: about {ram} bytes (rough; the Arduino core and libraries add more)."]
    libs = libraries(ck)
    if libs:
        L += ["", "Arduino libraries needed: " + ", ".join(libs)]
    return "\n".join(L) + "\n"
